namespace Clicky.Core.Hotkeys;

/// <summary>One keyboard transition as a low-level keyboard hook sees it.</summary>
/// <param name="Vk">Virtual-key code. Side-specific for modifiers (VK_LCONTROL, VK_RMENU, ...).</param>
/// <param name="ScanCode">Hardware scan code. Bit 0x200 marks keys synthesized by the layout driver (AltGr's fake LCtrl).</param>
/// <param name="IsDown">Key down (including auto-repeat) or key up.</param>
/// <param name="IsExtended">Extended-key flag (right-hand Ctrl/Alt, arrows, numpad Enter, ...).</param>
/// <param name="IsInjected">Generated by SendInput rather than a keyboard.</param>
/// <param name="TimestampMs">Monotonic milliseconds on the same clock the engine is ticked with.</param>
public readonly record struct KeyEvent(int Vk, int ScanCode, bool IsDown, bool IsExtended, bool IsInjected, long TimestampMs);
